CREATE VIEW agent_raw.salary_summary WITH (security_barrier) AS
SELECT * FROM (
  SELECT d.name AS department, CASE WHEN e.grade BETWEEN 1 AND 3 THEN '1-3' WHEN e.grade BETWEEN 4 AND 6 THEN '4-6' WHEN e.grade BETWEEN 7 AND 9 THEN '7-9' WHEN e.grade BETWEEN 10 AND 12 THEN '10-12' WHEN e.grade BETWEEN 13 AND 15 THEN '13-15' END AS grade_band, count(*) AS headcount,
         round(avg(p.salary_credits), -3) AS average_salary_credits, 'CONFIDENTIAL'::text AS sensitivity
  FROM empire.employees e JOIN empire.employee_private p USING (employee_id) JOIN empire.departments d USING (department_id)
  WHERE e.status = 'ACTIVE' GROUP BY 1, 2 HAVING count(*) >= 5
) t WHERE (SELECT rank FROM agent_private.label_ranks WHERE label = t.sensitivity) <= (SELECT r.rank FROM agent_private.role_levels l JOIN agent_private.label_ranks r USING (label) WHERE l.role_name = current_user);
COMMENT ON VIEW agent_raw.salary_summary IS 'Active employees by department and grade band: headcount and average salary in credits, rounded to 1,000. Only groups of 5 or more.';
CREATE VIEW agent_raw.review_summary WITH (security_barrier) AS
SELECT * FROM (
  SELECT d.name AS department, r.cycle_year, count(*) AS reviews, round(avg(r.rating), 2) AS average_rating,
         round(avg(r.salary_increase_pct), 1) AS average_salary_increase_pct, 'CONFIDENTIAL'::text AS sensitivity
  FROM empire.performance_reviews r JOIN empire.employees e USING (employee_id) JOIN empire.departments d USING (department_id)
  GROUP BY 1, 2 HAVING count(*) >= 5
) t WHERE (SELECT rank FROM agent_private.label_ranks WHERE label = t.sensitivity) <= (SELECT r.rank FROM agent_private.role_levels l JOIN agent_private.label_ranks r USING (label) WHERE l.role_name = current_user);
COMMENT ON VIEW agent_raw.review_summary IS 'Performance reviews by department and cycle year: count, average rating (1-5) and average salary increase in percent. Only groups of 5 or more.';
