CREATE VIEW agent.performance_reviews WITH (security_barrier) AS SELECT * FROM agent_private.performance_reviews t WHERE (SELECT rank FROM agent_private.label_ranks WHERE label = t.sensitivity) <= (SELECT r.rank FROM agent_private.role_levels l JOIN agent_private.label_ranks r USING (label) WHERE l.role_name = current_user);
