CREATE VIEW agent.programs WITH (security_barrier) AS SELECT t.program_id, t.code, t.name, t.executive_sponsor_id, t.program_director_id, t.status, t.start_date, t.target_completion, t.budget_mcr, t.sensitivity FROM empire.programs t WHERE (SELECT rank FROM agent_private.label_ranks WHERE label = t.sensitivity) <= (SELECT r.rank FROM agent_private.role_levels l JOIN agent_private.label_ranks r USING (label) WHERE l.role_name = current_user);
COMMENT ON VIEW agent.programs IS 'Company programs with their total budget in millions of credits (Mcr).';
CREATE VIEW agent.systems WITH (security_barrier) AS SELECT t.system_code, t.name, t.lead_department_id, t.summary, t.sensitivity FROM empire.systems t WHERE (SELECT rank FROM agent_private.label_ranks WHERE label = t.sensitivity) <= (SELECT r.rank FROM agent_private.role_levels l JOIN agent_private.label_ranks r USING (label) WHERE l.role_name = current_user);
COMMENT ON VIEW agent.systems IS 'Station subsystems.';
CREATE MATERIALIZED VIEW agent_private.suppliers AS SELECT t.supplier_id, t.name, t.homeworld, agent_private.pseudonym('PERSON', (t.contact_name)::text) AS contact_name, agent_private.pseudonym('EMAIL', (t.contact_email)::text) AS contact_email, t.status, t.performance_rating, t.sensitivity FROM empire.suppliers t;
CREATE VIEW agent.suppliers WITH (security_barrier) AS SELECT * FROM agent_private.suppliers t WHERE (SELECT rank FROM agent_private.label_ranks WHERE label = t.sensitivity) <= (SELECT r.rank FROM agent_private.role_levels l JOIN agent_private.label_ranks r USING (label) WHERE l.role_name = current_user);
COMMENT ON VIEW agent.suppliers IS 'Suppliers and their main contact. Personal values are pseudonyms (KIND_hex): the same value always has the same one.';
