CREATE MATERIALIZED VIEW agent_private.documents AS SELECT t.document_id, t.bucket, t.object_key, t.uri, t.doc_number, agent_private.scrub_names(t.title) AS title, t.doc_type, t.format, t.revision, t.approval_status, t.system_code, t.program_id, t.author_id, t.approver_id, t.created_date, t.approved_date, t.language, t.supersedes_document_id, t.size_bytes, t.sha256, t.sensitivity FROM empire.documents t;
CREATE VIEW agent.documents WITH (security_barrier) AS SELECT * FROM agent_private.documents t WHERE (SELECT rank FROM agent_private.label_ranks WHERE label = t.sensitivity) <= (SELECT r.rank FROM agent_private.role_levels l JOIN agent_private.label_ranks r USING (label) WHERE l.role_name = current_user);
COMMENT ON VIEW agent.documents IS 'Registry of every object in the tenant''s bucket. sensitivity is the label the document is filed under. Personal values are pseudonyms (KIND_hex): the same value always has the same one.';
CREATE VIEW agent.document_access_log WITH (security_barrier) AS SELECT t.log_id, t.accessed_at, t.employee_id, t.document_id, t.action, t.terminal_id, t.result, t.sensitivity FROM empire.document_access_log t WHERE (SELECT rank FROM agent_private.label_ranks WHERE label = t.sensitivity) <= (SELECT r.rank FROM agent_private.role_levels l JOIN agent_private.label_ranks r USING (label) WHERE l.role_name = current_user);
COMMENT ON VIEW agent.document_access_log IS 'Document opens, January to September 2026 (UTC).';
CREATE VIEW agent.salary_summary WITH (security_barrier) AS
SELECT * FROM (
  SELECT d.name AS department, CASE WHEN e.grade BETWEEN 1 AND 3 THEN '1-3' WHEN e.grade BETWEEN 4 AND 6 THEN '4-6' WHEN e.grade BETWEEN 7 AND 9 THEN '7-9' WHEN e.grade BETWEEN 10 AND 12 THEN '10-12' WHEN e.grade BETWEEN 13 AND 15 THEN '13-15' END AS grade_band, count(*) AS headcount,
         round(avg(p.salary_credits), -3) AS average_salary_credits, 'CONFIDENTIAL'::text AS sensitivity
  FROM empire.employees e JOIN empire.employee_private p USING (employee_id) JOIN empire.departments d USING (department_id)
  WHERE e.status = 'ACTIVE' GROUP BY 1, 2 HAVING count(*) >= 5
) t WHERE (SELECT rank FROM agent_private.label_ranks WHERE label = t.sensitivity) <= (SELECT r.rank FROM agent_private.role_levels l JOIN agent_private.label_ranks r USING (label) WHERE l.role_name = current_user);
COMMENT ON VIEW agent.salary_summary IS 'Active employees by department and grade band: headcount and average salary in credits, rounded to 1,000. Only groups of 5 or more.';
CREATE VIEW agent.review_summary WITH (security_barrier) AS
SELECT * FROM (
  SELECT d.name AS department, r.cycle_year, count(*) AS reviews, round(avg(r.rating), 2) AS average_rating,
         round(avg(r.salary_increase_pct), 1) AS average_salary_increase_pct, 'CONFIDENTIAL'::text AS sensitivity
  FROM empire.performance_reviews r JOIN empire.employees e USING (employee_id) JOIN empire.departments d USING (department_id)
  GROUP BY 1, 2 HAVING count(*) >= 5
) t WHERE (SELECT rank FROM agent_private.label_ranks WHERE label = t.sensitivity) <= (SELECT r.rank FROM agent_private.role_levels l JOIN agent_private.label_ranks r USING (label) WHERE l.role_name = current_user);
COMMENT ON VIEW agent.review_summary IS 'Performance reviews by department and cycle year: count, average rating (1-5) and average salary increase in percent. Only groups of 5 or more.';
